/** Numbered history stays in src as engine stays, placed through the candidate's canonical plan command [C7,D3,H16]. */
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { cleanGitEnvironment } from './git.js';
import { git } from './git.js';
import { Refused } from './refused.js';

/** Place only histories generated by this allocation; unrelated projects without a cells plan stay untouched. */
export function placeLandingHistory(root, files) {
  const histories = files.filter(file => /^src\/move-history\/\d+\.json$/u.test(file));
  if (!histories.length || !existsSync(join(root, 'bin/cells-plan.json'))) return [];
  for (const file of histories) {
    const result = spawnSync(process.execPath, ['bin/cells-plan.js', '--place', file, '--stay'], {
      cwd: root, env: cleanGitEnvironment(), timeout: 30_000, maxBuffer: 32 * 1024 * 1024,
    });
    if (result.status !== 0) throw new Refused('LAND_MERGE', `canonical state rule placement failed for ${file}; repair the cells plan and retry landing`);
  }
  return git(root, ['diff', '--name-only', 'HEAD', '--', 'bin/cells-plan.json', 'bin/cells-plan/']).split('\n').filter(Boolean);
}
